def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key = op[2]
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]
            if key not in cache and len(cache) >= capacity:
                # need to evict, but only if adding a new key
                # check capacity based on current live entries count == capacity
                # remove expired entries first? Problem says expired counts as absent
                # so we should evict least recently used *non-expired* logically,
                # but expired entries still occupy space unless we purge them.
                # We purge expired entries lazily to keep capacity semantics correct.
                pass
            # Remove any expired entries to keep the cache size accurate before eviction check
            expired_keys = [k for k in cache if is_expired(k, t)]
            for k in expired_keys:
                del cache[k]
            if key not in cache and len(cache) >= capacity:
                # evict least recently used
                cache.popitem(last=False)
            cache[key] = (value, t)
            cache.move_to_end(key)
        elif kind == 'get':
            key = op[2]
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)
    return results

